"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["34960"],{44813(e){e.exports=JSON.parse('{"id":"V4-035","slug":"bretton-woods-system","term":"Bretton Woods System","also_known_as":[],"difficulty":"Intermediate","definition":"The Bretton Woods system was an international monetary system created in 1944, under which major currencies were pegged to the US dollar, and the dollar was convertible into gold at a fixed price.","explanation":["Representatives of 44 countries met at Bretton Woods, New Hampshire, in 1944 to design a stable post-war monetary system. Countries fixed their currencies to the US dollar within narrow bands, and the United States agreed to exchange dollars for gold with other countries\u2019 central banks at 35 dollars per ounce. The conference also created the International Monetary Fund and the World Bank.","The system supported strong growth in trade and the post-war recovery. Over time, however, the United States\u2019 gold reserves became insufficient to back the growing number of dollars held abroad, and confidence weakened.","In 1971, President Richard Nixon suspended the dollar\u2019s convertibility into gold. Attempts to maintain fixed exchange rates continued briefly, but by 1973 the major currencies were floating.","The end of Bretton Woods led to today\u2019s system of mostly floating exchange rates among major currencies. The dollar nonetheless remained the world\u2019s main reserve currency, and the institutions created at Bretton Woods continue to play central roles in the global economy."],"note":"","total":1725,"prev":{"slug":"break-fee","term":"Break Fee"},"next":{"slug":"bridge-loan","term":"Bridge Loan"}}')}}]);